import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 * @property {{imageUrl:string}} assets
 * @property {string} textContent
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {{textureLoader: {load:(url:string)=>THREE.Texture}}} textureLoader
 * @property {{fontAtlas:any}} fontAtlas
 * @property {{primitives:Record<string, (obj:THREE.Object3D, params:any)=>void>}} primitives
 * @property {{text:{createText:(options:any)=>THREE.Object3D}}} text
 */

/**
 * Create a pricing card label node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // Container for the whole element
  const container = new THREE.Object3D();

  // ----- Plane with texture -------------------------------------------------
  const tex = ctx.textureLoader.load(config.assets.imageUrl);
  tex.minFilter = THREE.LinearMipmapLinearFilter;
  tex.magFilter = THREE.LinearFilter;
  tex.generateMipmaps = true;
  tex.needsUpdate = true;

  // Create a unit plane; we'll scale it later based on texture aspect
  const planeGeo = new THREE.PlaneGeometry(1, 1);
  const planeMat = new MeshBasicNodeMaterial({ map: tex });
  const planeMesh = new THREE.Mesh(planeGeo, planeMat);
  planeMesh.renderOrder = 0;

  // Adjust plane size to keep texture aspect ratio
  const aspect = tex.image?.width ? tex.image.width / tex.image.height : 1;
  planeMesh.scale.set(aspect, 1, 1);

  // Add plane to container
  container.add(planeMesh);

  // ----- MSDF Text ---------------------------------------------------------
  const textObj = ctx.text.createText({
    content: config.textContent,
    fontAtlas: ctx.fontAtlas,
    atlasRegion: { atlas: 0, rect: [0, 0, 512, 320] },
    // headline size based on design token (approx 0.34 scene units)
    size: 0.34,
    // color from design tokens: primary ink
    color: 0x16161d,
    // align centre
    align: 'center',
  });

  // Position text slightly in front of the plane to avoid z‑fighting
  textObj.position.set(0, 0, 0.001);
  container.add(textObj);

  // ----- Apply cinematic primitives (if any) ------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(container, prim.params);
      }
    }
  }

  // ----- Transform ---------------------------------------------------------
  if (config.position) {
    container.position.set(config.position.x, config.position.y, config.position.z);
  }
  if (config.rotation) {
    container.rotation.set(config.rotation.x, config.rotation.y, config.rotation.z);
  }
  if (config.scale) {
    container.scale.set(config.scale.x, config.scale.y, config.scale.z);
  }

  // ----- Event handlers placeholder -----------------------------------------
  container.userData.handlers = {};

  // ----- Cleanup -----------------------------------------------------------
  const timelines = []; // No timelines currently, placeholder for future use

  container.userData.cleanup = () => {
    // Dispose GSAP timelines
    for (const tl of timelines) {
      tl.kill();
    }
    // Dispose Three.js resources
    planeGeo.dispose();
    planeMat.dispose();
    if (tex) tex.dispose();
    if (textObj && typeof textObj.dispose === 'function') {
      textObj.dispose();
    }
  };

  return container;
}
